static void
asymmetric_bmag(double t, const double *xn, double *out, void *ctx)
{
  int profile = *(int *)ctx;
  if (profile == 0) {
    out[0] = xn[0] < 0.25 ? 2.0 - xn[0] : 1.75 + 2.0 * (xn[0] - 0.25);
